class Solution {
    public List<String> findRepeatedDnaSequences(String s){
        Set<String> seen=new HashSet<>();
        Set<String> repeated=new LinkedHashSet<>();
        for(int i=0;i+10<=s.length();i++){
            String part=s.substring(i,i+10);
            if(!seen.add(part)) repeated.add(part);
        }
        return new ArrayList<>(repeated);
    }
}

code.kotlin:
class Solution {
    fun findRepeatedDnaSequences(s:String):List<String>{
        val seen=hashSetOf<String>();
        val repeated=linkedSetOf<String>();
        for(i in 0..s.length-10){
            val part=s.substring(i,i+10);
            if(!seen.add(part)) repeated.add(part)
        };
        return repeated.toList()
    }
}

code.cpp:
class Solution {
    public: vector<string> findRepeatedDnaSequences(string s){
        unordered_set<string> seen,added;
        vector<string> answer;
        for(int i=0;i+10<=(int)s.size();++i){
            string part=s.substr(i,10);
            if(!seen.insert(part).second && added.insert(part).second) answer.push_back(part);
        }
        return answer;
    }
};
